def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    v3 = vars["v3"]
    net_effect = v1 + v2 + v3
    return {
        "value": net_effect,
        "trace": {
            "v1": v1,
            "v2": v2,
            "v3": v3,
            "net_effect": net_effect,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
